\section{Introduction}

The number of points of an elliptic curve over a finite field is its fundamental arithmetic
invariant. Hasse's theorem asserts that for a nonsingular curve over $\F_q$,
\[
\bigl|\,\#E(\F_q)-(q+1)\,\bigr|\le 2\sqrt q ,
\]
and the standard proof proceeds through the endomorphism ring, the Frobenius endomorphism
acting on the Jacobian, and positivity of the degree pairing.

The purpose of this paper is to see how far one can get with none of that machinery. The
starting point is the elementary identity
\[
\#\{y\in F: y^2=c\}=\chi(c)+1 ,
\]
where $\chi$ is the quadratic character. This turns point counting into character-sum
evaluation, and a surprisingly rich body of \emph{exact} results follows.

The methodological theme is that the fluctuation of the point count around $q+1$ is a
character sum, and character sums of polynomials of degree at most two are computable in
closed form. Degree three --- the elliptic case --- is precisely where the elementary
method stops giving pointwise information. But \emph{averages} of cubic sums reduce, by
exchanging the order of summation, back to quadratic sums, and so are computable. That
reduction is the engine of Sections~\ref{sec:second} and~\ref{sec:vertical}.

\medskip
\noindent\textbf{Organization.} Section~\ref{sec:setup} derives the counting formula.
Section~\ref{sec:parity} treats parity, $2$-torsion and the root dichotomy.
Section~\ref{sec:ss} treats supersingular families, twisting and modular invariants.
Section~\ref{sec:second} computes the exact second moment.
Section~\ref{sec:vertical} computes all quadratic character sums, the relevant conic count,
the exact vertical moments and the cubic/quadratic bridge.
Section~\ref{sec:numeric} reports exhaustive computations, and
Section~\ref{sec:discussion} discusses limits and future directions.

\section{Setup and the counting formula}\label{sec:setup}

Throughout, $F$ is a finite field with $q=\#F$ and $\charc F\ne 2$.

\begin{definition}
The \emph{quadratic character} $\chi:F\to\{-1,0,1\}$ is defined by $\chi(0)=0$, $\chi(c)=1$
if $c$ is a nonzero square, and $\chi(c)=-1$ otherwise. It is multiplicative and satisfies
$\sum_{c\in F}\chi(c)=0$.
\end{definition}

\begin{definition}
For $a,b\in F$ put $f_{a,b}(x)=x^3+ax+b$. The \emph{affine locus} is
$A_{a,b}=\{(x,y)\in F^2: y^2=f_{a,b}(x)\}$ and the \emph{point count} is
$\#E_{a,b}=\#A_{a,b}+1$. The \emph{trace of Frobenius} is $a(a,b)=q+1-\#E_{a,b}$, the
\emph{character sum} is $S(a,b)=\sum_{x\in F}\chi(f_{a,b}(x))$, the \emph{root set} is
$R_{a,b}=\{x\in F: f_{a,b}(x)=0\}$, and the \emph{discriminant quantity} is
$\Delta(a,b)=4a^3+27b^2$. The curve is \emph{nonsingular} when $\Delta(a,b)\ne 0$.
\end{definition}

\begin{lemma}[Square-root count]\label{lem:sqrt}
For every $c\in F$, $\ \#\{y\in F: y^2=c\}=\chi(c)+1$.
\end{lemma}

\begin{proof}[Proof sketch]
If $c=0$ the unique root is $y=0$ and $\chi(0)+1=1$. If $c=e^2\ne 0$ the roots are $\pm e$,
distinct because $\charc F\ne 2$, and $\chi(c)+1=2$. If $c$ is a nonsquare there are no
roots and $\chi(c)+1=0$.
\end{proof}

\begin{theorem}[Counting formula]\label{thm:count}
For all $a,b\in F$,
\[
\#A_{a,b}=q+S(a,b),\qquad \#E_{a,b}=q+1+S(a,b),\qquad a(a,b)=-S(a,b).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Partition $A_{a,b}$ by the value of $x$. By Lemma~\ref{lem:sqrt} the fibre over $x$ has
$\chi(f_{a,b}(x))+1$ elements; summing over the $q$ values of $x$ gives
$\#A_{a,b}=q+S(a,b)$. The other two identities are rearrangements.
\end{proof}

\section{Parity, $2$-torsion and the root dichotomy}\label{sec:parity}

\begin{lemma}\label{lem:par}
$S(a,b)\equiv q-\#R_{a,b}\pmod 2$.
\end{lemma}

\begin{proof}[Proof sketch]
Term by term: $\chi(f_{a,b}(x))$ is $0$ for $x\in R_{a,b}$ and $\pm1$ otherwise, and
$\pm1\equiv1\pmod2$. Hence $S(a,b)$ is congruent mod $2$ to $\#\{x\notin R_{a,b}\}$.
\end{proof}

\begin{corollary}\label{cor:par}
$\#E_{a,b}\equiv 1+\#R_{a,b}\pmod 2$.
\end{corollary}

\begin{lemma}[Two roots determine the coefficients]\label{lem:tworoots}
If $r\ne s$ and $f_{a,b}(r)=f_{a,b}(s)=0$, then $a=-(r^2+rs+s^2)$ and $b=rs(r+s)$, and
consequently $f_{a,b}(u)=(u-r)(u-s)(u+r+s)$ for all $u$.
\end{lemma}

\begin{proof}[Proof sketch]
Subtracting the two vanishing conditions gives $(r-s)(r^2+rs+s^2+a)=0$; since $r\ne s$ the
second factor vanishes, determining $a$, and substituting back into $f_{a,b}(r)=0$
determines $b$. The factorization follows by expansion.
\end{proof}

\begin{theorem}[$0/1/3$ dichotomy]\label{thm:dich}
If $\Delta(a,b)\ne0$ then $\#R_{a,b}\in\{0,1,3\}$.
\end{theorem}

\begin{proof}[Proof sketch]
If $\#R_{a,b}\ge2$, pick distinct roots $r,s$. By Lemma~\ref{lem:tworoots} the cubic
factors as $(u-r)(u-s)(u+r+s)$, so $R_{a,b}=\{r,s,-(r+s)\}$. If $r=-(r+s)$ then $s=-2r$,
and substituting the resulting $a,b$ into $\Delta=4a^3+27b^2$ gives $\Delta=0$,
contradicting nonsingularity; the case $s=-(r+s)$ is symmetric. Hence exactly three
distinct roots.
\end{proof}

\begin{theorem}[$2$-torsion criterion]\label{thm:2tors}
If $\Delta(a,b)\ne 0$ then $2\mid\#E_{a,b}$ if and only if $x^3+ax+b=0$ has a solution in $F$.
\end{theorem}

\begin{proof}[Proof sketch]
By Corollary~\ref{cor:par}, $\#E_{a,b}$ is even iff $\#R_{a,b}$ is odd; by
Theorem~\ref{thm:dich}, $\#R_{a,b}\in\{0,1,3\}$, so this happens iff $\#R_{a,b}\ne0$.
\end{proof}

Geometrically, a root $r$ gives the point $(r,0)$, which is its own inverse in the group
law and hence of order two; the theorem supplies the converse.

\begin{remark}[Sharpness]
Nonsingularity cannot be dropped. Over $\F_5$ take $(a,b)=(2,2)$: then $\Delta\equiv0$, the
cubic factors as $(x-1)^2(x+2)$ and has exactly the two distinct roots $\{1,3\}$ --- the
value excluded by Theorem~\ref{thm:dich} --- while the point count is $7$, odd, despite a
root existing.
\end{remark}

\section{Supersingular families, twisting and modular invariants}\label{sec:ss}

\begin{theorem}\label{thm:cubefam}
If $x\mapsto x^3$ is a bijection of $F$, then $S(0,b)=0$ for every $b$, hence
$\#E_{0,b}=q+1$ and $a(0,b)=0$.
\end{theorem}

\begin{proof}[Proof sketch]
Reindex along the bijection: $S(0,b)=\sum_x\chi(x^3+b)=\sum_t\chi(t+b)=\sum_u\chi(u)=0$.
\end{proof}

\begin{lemma}\label{lem:cubebij}
If $\gcd(q-1,3)=1$ then $x\mapsto x^3$ is a bijection of $F$.
\end{lemma}

\begin{proof}[Proof sketch]
On the cyclic group $F^\times$ of order $q-1$, the cube map is bijective when $3$ is
coprime to the group order; and $0\mapsto0$. Injectivity on the finite set $F$ implies
bijectivity.
\end{proof}

\begin{corollary}[Modular invariant mod $3$]\label{cor:mod3}
Let $p>2$ be prime with $p\equiv2\pmod3$. Then for every $b\in\F_p$ the curve $y^2=x^3+b$
has exactly $p+1$ points and $a(0,b)=0$; in particular $3\mid\#E_{0,b}$.
\end{corollary}

\begin{theorem}\label{thm:linfam}
If $\chi(-1)=-1$ then $S(a,0)=0$ for every $a$, hence $\#E_{a,0}=q+1$ and $a(a,0)=0$.
\end{theorem}

\begin{proof}[Proof sketch]
$f_{a,0}$ is odd, so $\chi(f_{a,0}(-x))=\chi(-1)\chi(f_{a,0}(x))=-\chi(f_{a,0}(x))$.
Summing over $x$ and using that $x\mapsto-x$ permutes $F$ gives $S(a,0)=-S(a,0)$.
\end{proof}

\begin{corollary}[Modular invariant mod $4$]\label{cor:mod4}
Let $p\equiv3\pmod4$ be prime. Then for every $a\in\F_p$ the curve $y^2=x^3+ax$ has exactly
$p+1$ points and $a(a,0)=0$; in particular $4\mid\#E_{a,0}$.
\end{corollary}

\begin{remark}
For $a\ne0$ the curve $y^2=x^3+ax$ always carries the $2$-torsion point $(0,0)$, so by
Theorem~\ref{thm:2tors} its point count is even for every odd $p$ --- consistent with, but
weaker than, Corollary~\ref{cor:mod4}. The congruence conditions are essential: over
$\F_{13}$, which is $1$ mod $3$ and $1$ mod $4$, the curves $y^2=x^3+1$ and $y^2=x^3+2$
have $12$ and $19$ points.
\end{remark}

\begin{theorem}[Twisting]\label{thm:twist}
Let $d\in F$ with $\chi(d)=-1$. Then for all $a,b$,
\[
S(ad^2,bd^3)=-S(a,b),\qquad a(ad^2,bd^3)=-a(a,b),\qquad
\#E_{a,b}+\#E_{ad^2,bd^3}=2q+2 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The substitution $x=du$ gives $f_{ad^2,bd^3}(du)=d^3f_{a,b}(u)$, and $\chi(d^3)=\chi(d)^3=-1$.
As $u$ ranges over $F$ so does $du$, whence the first identity; the rest follows from
Theorem~\ref{thm:count}.
\end{proof}

\begin{corollary}[Vanishing first moment]\label{cor:first}
For every $a$, $\sum_{b}S(a,b)=0$; hence $\sum_{a,b}a(a,b)=0$ and
$\sum_{a,b}\#E_{a,b}=q^2(q+1)$.
\end{corollary}

\begin{proof}[Proof sketch]
Exchange summation: $\sum_bS(a,b)=\sum_x\sum_b\chi\bigl((x^3+ax)+b\bigr)$, and for fixed $x$
the inner sum runs over a translate of $F$, hence equals $\sum_u\chi(u)=0$.
\end{proof}

Thus the average curve in the family has exactly $q+1$ points.

\section{The exact second moment}\label{sec:second}

\begin{lemma}\label{lem:shift}
Let $\charc F\ne2$ and $w\ne0$. Then $\displaystyle\sum_{c\in F}\chi\bigl(c(c+w)\bigr)=-1$.
\end{lemma}

\begin{proof}[Proof sketch]
The $c=0$ term vanishes; for $c\ne0$ factor $c(c+w)=c^2(1+wc^{-1})$ and use $\chi(c^2)=1$.
The map $c\mapsto 1+wc^{-1}$ is a bijection $F\setminus\{0\}\to F\setminus\{1\}$ with
inverse $t\mapsto w(t-1)^{-1}$, so the sum is $\sum_{t\ne1}\chi(t)=0-\chi(1)=-1$.
\end{proof}

\begin{lemma}[Two-shift correlation]\label{lem:pair}
For $u,v\in F$,
\[
\sum_{b\in F}\chi\bigl((b+u)(b+v)\bigr)=
\begin{cases} q-1, & u=v,\\ -1, & u\ne v.\end{cases}
\]
\end{lemma}

\begin{proof}[Proof sketch]
Substituting $b=c-u$ reduces to $\sum_c\chi\bigl(c(c+(v-u))\bigr)$. For $u=v$ this is
$\sum_c\chi(c^2)=q-1$; for $u\ne v$ apply Lemma~\ref{lem:shift} with $w=v-u$.
\end{proof}

\begin{definition}
For $a\in F$ let $N(a)=\#\{(x,y)\in F^2:\ x^3+ax=y^3+ay\}$ be the \emph{collision count}.
\end{definition}

\begin{proposition}[Vertical moment via collisions]\label{prop:vert}
For all $a\in F$, $\ \sum_{b\in F}S(a,b)^2=q\,N(a)-q^2$.
\end{proposition}

\begin{proof}[Proof sketch]
Expand $S(a,b)^2=\sum_{x,y}\chi\bigl(f_{a,b}(x)f_{a,b}(y)\bigr)$ and sum over $b$ innermost.
With $u=x^3+ax$ and $v=y^3+ay$ we have $f_{a,b}(x)f_{a,b}(y)=(b+u)(b+v)$, so by
Lemma~\ref{lem:pair} the inner sum is $-1+q\,\one[u=v]$. Summing over the $q^2$ pairs
$(x,y)$ gives $-q^2+qN(a)$.
\end{proof}

\begin{lemma}[Horizontal correlation]\label{lem:horiz}
For $x,y\in F$,
\[
\sum_{a\in F}\Bigl(-1+q\,\one\bigl[x^3+ax=y^3+ay\bigr]\Bigr)=
\begin{cases}q^2-q,& x=y,\\ 0,& x\ne y.\end{cases}
\]
\end{lemma}

\begin{proof}[Proof sketch]
For $x=y$ the indicator is always $1$. For $x\ne y$ the condition factors as
$(x-y)(x^2+xy+y^2+a)=0$, so it holds for exactly one $a$, namely $a=-(x^2+xy+y^2)$; the sum
is then $-q+q=0$.
\end{proof}

\begin{theorem}[Exact second moment]\label{thm:secondmoment}
Let $\charc F\ne2$. Then
\[
\sum_{a\in F}\sum_{b\in F}S(a,b)^2=q^3-q^2,
\qquad\text{equivalently}\qquad
\sum_{a,b}a(a,b)^2=q^3-q^2 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
By the proof of Proposition~\ref{prop:vert},
$\sum_a\sum_bS(a,b)^2=\sum_x\sum_y\sum_a\bigl(-1+q\one[x^3+ax=y^3+ay]\bigr)$. By
Lemma~\ref{lem:horiz} the inner sum contributes $q^2-q$ on the diagonal and $0$ off it, so
the total is $q(q^2-q)=q^3-q^2$. Finally $a(a,b)^2=S(a,b)^2$.
\end{proof}

Dividing by the number $q^2$ of parameter pairs, the mean square of the trace of Frobenius
over the family is \emph{exactly} $q-1$: the square-root heuristic is an identity with no
error term.

\begin{theorem}[Chebyshev; Hasse on average]\label{thm:cheb}
For every $K\in\Z$,
\[
K\cdot\#\{(a,b)\in F^2:\ a(a,b)^2\ge K\}\ \le\ q^3-q^2 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
On the set $T$ of such pairs, $K\,\#T\le\sum_{T}a(a,b)^2$, and since all terms are
nonnegative this is at most the full sum $q^3-q^2$.
\end{proof}

\begin{corollary}
For every $\lambda>0$ the number of pairs with $|a(a,b)|\ge\lambda\sqrt q$ is at most
$q^2/\lambda^2$. In particular at most a quarter of the family could violate the Hasse
bound.
\end{corollary}

\begin{theorem}[Extremal existence]\label{thm:extremal}
There exist $a,b\in F$ with $a(a,b)^2\ge q-1$.
\end{theorem}

\begin{proof}[Proof sketch]
Otherwise every term is at most $q-2$ and the total is at most $q^2(q-2)=q^3-2q^2<q^3-q^2$,
contradicting Theorem~\ref{thm:secondmoment}.
\end{proof}

Combined with Hasse's theorem, the extremal trace in the family lies between $\sqrt{q-1}$
and $2\sqrt q$.

\section{Complete quadratic sums, the conic, and the vertical moments}\label{sec:vertical}

In this section $\charc F\notin\{2,3\}$.

\begin{lemma}[Roots of a quadratic]\label{lem:quadroots}
For $\beta,\gamma\in F$, $\ \#\{y: y^2+\beta y+\gamma=0\}=\chi(\beta^2-4\gamma)+1$.
\end{lemma}

\begin{proof}[Proof sketch]
Substituting $y=z-\beta/2$ turns the condition into $z^2=(\beta^2-4\gamma)/4$, and $\chi$
is unchanged by the nonzero square factor $1/4$; apply Lemma~\ref{lem:sqrt}.
\end{proof}

\begin{lemma}[Hyperbola count]\label{lem:hyp}
For $D\in F$, $\ \#\{(u,t): t^2=u^2-D\}=2q-1$ if $D=0$ and $q-1$ if $D\ne0$.
\end{lemma}

\begin{proof}[Proof sketch]
The bijection $(s,r)\mapsto(u,t)=\bigl((s+r)/2,(r-s)/2\bigr)$ of $F^2$ transforms
$t^2=u^2-D$ into $sr=D$. For $D\ne0$ each $s\ne0$ has exactly one $r$; for $D=0$ the locus
is the union of the two axes.
\end{proof}

\begin{lemma}\label{lem:shiftsq}
$\displaystyle\sum_{u\in F}\chi(u^2-D)=q-1$ if $D=0$, and $-1$ if $D\ne0$.
\end{lemma}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:sqrt}, $\chi(u^2-D)=\#\{t:t^2=u^2-D\}-1$; sum over $u$ and apply
Lemma~\ref{lem:hyp}.
\end{proof}

\begin{theorem}[Complete quadratic character sum]\label{thm:quadsum}
Let $\alpha\ne0$ and $\beta,\gamma\in F$. Then
\[
\sum_{v\in F}\chi(\alpha v^2+\beta v+\gamma)=
\begin{cases}(q-1)\chi(\alpha), & \beta^2-4\alpha\gamma=0,\\[2pt]
-\chi(\alpha), & \beta^2-4\alpha\gamma\ne0.\end{cases}
\]
\end{theorem}

\begin{proof}[Proof sketch]
Multiply inside by $\alpha$ and complete the square:
$\alpha(\alpha v^2+\beta v+\gamma)=(\alpha v+\beta/2)^2-D$ with $D=\beta^2/4-\alpha\gamma$.
Since $\chi(\alpha)^2=1$ we get
$\chi(\alpha v^2+\beta v+\gamma)=\chi(\alpha)\chi\bigl((\alpha v+\beta/2)^2-D\bigr)$. As $v$
runs over $F$ so does $\alpha v+\beta/2$; apply Lemma~\ref{lem:shiftsq}, noting
$D=0\iff\beta^2-4\alpha\gamma=0$.
\end{proof}

\begin{theorem}[Conic count]\label{thm:conic}
For $c\in F$,
\[
\#\{(x,y)\in F^2:\ x^2+xy+y^2=c\}=q+
\begin{cases}(q-1)\chi(-3), & c=0,\\ -\chi(-3), & c\ne0.\end{cases}
\]
\end{theorem}

\begin{proof}[Proof sketch]
For fixed $x$ the equation is the quadratic $y^2+xy+(x^2-c)=0$, whose root count is
$\chi(-3x^2+4c)+1$ by Lemma~\ref{lem:quadroots}. Sum over $x$ and apply
Theorem~\ref{thm:quadsum} with $\alpha=-3\ne0$, $\beta=0$, $\gamma=4c$; the discriminant
$48c$ vanishes iff $c=0$.
\end{proof}

\begin{theorem}[Exact collision counts]\label{thm:coll}
With $\charc F\notin\{2,3\}$,
\[
N(0)=2q-1+(q-1)\chi(-3),\qquad
N(a)=2q-1-\chi(-3)-\chi(-a/3)\quad(a\ne0).
\]
\end{theorem}

\begin{proof}[Proof sketch]
The diagonal contributes $q$ pairs. Off the diagonal, $x^3+ax=y^3+ay$ is equivalent to
$x^2+xy+y^2=-a$. By inclusion--exclusion,
$N(a)=q+\#\{x^2+xy+y^2=-a\}-\#\{x:3x^2=-a\}$; Theorem~\ref{thm:conic} evaluates the conic
term with $c=-a$ and Lemma~\ref{lem:sqrt} evaluates the diagonal correction as
$\chi(-a/3)+1$.
\end{proof}

\begin{theorem}[Exact vertical second moments]\label{thm:vertmom}
With $\charc F\notin\{2,3\}$,
\[
\sum_{b\in F}a(0,b)^2=q(q-1)\bigl(1+\chi(-3)\bigr),
\]
and, for $a\ne0$,
\[
\sum_{b\in F}a(a,b)^2=q^2-q\bigl(1+\chi(-3)+\chi(-a/3)\bigr).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Substitute Theorem~\ref{thm:coll} into Proposition~\ref{prop:vert}, using
$a(a,b)^2=S(a,b)^2$.
\end{proof}

\begin{remark}[Consistency]
Summing the second formula over the $q-1$ nonzero $a$ and adding the first, and using
$\sum_{a\ne0}\chi(-a/3)=0$, gives $(q-1)q^2=q^3-q^2$, in agreement with
Theorem~\ref{thm:secondmoment}; the dependence on $\chi(-3)$ cancels exactly.
\end{remark}

\begin{corollary}\label{cor:ssiff}
The family $y^2=x^3+b$ satisfies $a(0,b)=0$ for every $b$ if and only if $\chi(-3)=-1$.
\end{corollary}

\begin{proof}[Proof sketch]
A sum of squares of integers vanishes iff each term does, so the condition is
$\sum_b a(0,b)^2=0$, i.e. $q(q-1)(1+\chi(-3))=0$; as $q>1$ and $\chi(-3)\in\{\pm1\}$, this
holds iff $\chi(-3)=-1$.
\end{proof}

\begin{theorem}[Cubic/quadratic bridge]\label{thm:bridge}
With $\charc F\notin\{2,3\}$, the map $x\mapsto x^3$ is a bijection of $F$ if and only if
$\chi(-3)=-1$.
\end{theorem}

\begin{proof}[Proof sketch]
The collision locus $\{(x,y):x^3=y^3\}$ equals the diagonal precisely when cubing is
injective, i.e.\ (by finiteness) bijective, i.e.\ $N(0)=q$. By Theorem~\ref{thm:coll} this
says $(q-1)(\chi(-3)+1)=0$, i.e.\ $\chi(-3)=-1$.
\end{proof}

Equivalently, $F$ contains a primitive cube root of unity iff $-3$ is a square in $F$, the
cube roots of unity being $(-1\pm\sqrt{-3})/2$.

\begin{corollary}[Supplementary reciprocity for $-3$]\label{cor:recip}
Let $p>3$ be prime. Then $-3$ is a nonsquare modulo $p$ if and only if $p\equiv2\pmod3$.
\end{corollary}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:bridge} it suffices to show cubing is bijective on $\F_p$ iff
$p\equiv2\pmod3$. If $p\equiv2\pmod3$ then $3\nmid p-1$ and Lemma~\ref{lem:cubebij} applies.
If $p\equiv1\pmod3$ then $3\mid\#\F_p^\times$, so by Cauchy's theorem there is $z\ne1$ of
order $3$, and $z^3=1^3$ shows cubing is not injective.
\end{proof}

\section{Exhaustive verification over small prime fields}\label{sec:numeric}

The following were verified by exhaustive enumeration.

\begin{enumerate}
\item \textbf{Hasse's bound.} For $p\in\{5,7,11,13\}$, $a(a,b)^2\le 4p$ for all $p^2$
parameter pairs. Observed maxima of $a(a,b)^2$: $16,25,36,49$ against $4p=20,28,44,52$.
\item \textbf{Second moment.} For $p\in\{5,7,11,13,17,19\}$, $\sum_{a,b}a(a,b)^2=p^3-p^2$
exactly: $100,294,1210,2028,4624,6498$.
\item \textbf{Supersingular families.} Over $\F_{11}$ (which is $2$ mod $3$ and $3$ mod
$4$) both $\#E_{0,b}=12$ for all $b$ and $\#E_{a,0}=12$ for all $a$.
\item \textbf{Non-degeneracy.} Over $\F_{13}$: $\#E_{0,1}=12\ne19=\#E_{0,2}$.
\item \textbf{Parity criterion.} Over $\F_5$: $y^2=x^3+1$ has the root $x=-1$ and $6$
points; $y^2=x^3+x+1$ has no root and $9$ points.
\item \textbf{Sharpness.} Over $\F_5$ the singular curve $y^2=x^3+2x+2$ has $\Delta=0$,
exactly two roots and $7$ points.
\item \textbf{Twisting.} Over $\F_5$ with $d=2$: $\#E_{1,1}=9$, $\#E_{4,3}=3$, sum $12=2\cdot5+2$.
\item \textbf{Vertical moments.} For $p\in\{5,7,11,13\}$ both formulas of
Theorem~\ref{thm:vertmom} hold for every $a$; e.g.\ $\sum_b a(0,b)^2=84$ at $p=7$ and $0$
at $p=11$.
\item \textbf{Bridge.} For $p\in\{5,7,11,13,17,19,23\}$ cubing is bijective exactly for
$p\in\{5,11,17,23\}$, exactly those with $\chi(-3)=-1$ and $p\equiv2\pmod3$.
\end{enumerate}

The empirical trace distribution over $\F_{11}$ is symmetric about $0$, supported on
$[-6,6]\subset[-2\sqrt{11},2\sqrt{11}]$, with mean $0$ and mean square exactly $10=p-1$.

\section{Discussion and future directions}\label{sec:discussion}

\subsection*{What the method reaches}
The machinery here is exactly powerful enough for character sums of degree at most two.
Every exact result arises because some manipulation reduces the cubic sum $S(a,b)$ to a
linear or quadratic one: the supersingular families by reindexing along $x\mapsto x^3$ or
$x\mapsto-x$; the moments by exchanging summation so that $b$, which occurs linearly in
$f_{a,b}$, is summed innermost; the vertical moments by the complete quadratic evaluation
(Theorem~\ref{thm:quadsum}) and the conic count (Theorem~\ref{thm:conic}), which is where
$\chi(-3)$ enters.

\subsection*{What it does not reach}
The gap is a \emph{pointwise} bound on $a(a,b)$ --- Hasse's theorem. This is a genuine
boundary: pointwise square-root cancellation for a cubic character sum is the Riemann
Hypothesis for the associated curve. The moment method gives the bound for all but a
$\lambda^{-2}$ fraction of the family, and exhaustive computation confirms it in the
accessible range.

\subsection*{Future directions}

\begin{conjecture}[Fourth moment]\label{conj:C1}
There are integers $c_3,c_2$ depending only on $\chi(-3)$ and $\chi(-1)$ with
\[
\sum_{a,b\in F}a(a,b)^4=2q^5-3q^4+c_3q^3+c_2q^2 .
\]
\end{conjecture}

The key insight is that the fourth moment reduces, exactly as the second moment did, to the
$b$-sum $\sum_b\chi\bigl((b+u_1)(b+u_2)(b+u_3)(b+u_4)\bigr)$, and that this sum is
elementary whenever the $u_i$ collide in pairs; the genuinely quartic case is the only
Weil-type input, and it is governed by a single hyperelliptic curve of genus one whose own
count is again in the family. So the fourth moment should be self-referential and computable
by the same collision bookkeeping as Theorem~\ref{thm:coll}. The machinery is already in
place --- only the degree-four shift sum is missing --- and a numerical table for
$q=5,7,11,13$ can pin $c_3,c_2$ in advance. A proof would give
$\#\{(a,b):|a|\ge\lambda\sqrt q\}=O(q^2/\lambda^4)$, improving Theorem~\ref{thm:cheb}.

\begin{conjecture}[Hasse from moments]\label{conj:C2}
For every $a,b$ with $\Delta(a,b)\ne0$ one has $a(a,b)^2\le4q$, and this is provable from
(i) the exact second moment, (ii) the twisting identity, and (iii) multiplicativity of the
count under base change $F\to F_{q^n}$ --- with no Riemann--Roch and no Jacobian.
\end{conjecture}

The key insight is that $a(a,b)^2\le4q$ is equivalent to positivity of $q^n+1-a_n$ on all
extensions, and $a_n$ satisfies the Newton recursion $a_{n+1}=a_1a_n-q\,a_{n-1}$, which one
may hope to \emph{derive} from moment identities over each $F_{q^n}$ rather than from the
Frobenius eigenvalue picture. The development above is stated for an arbitrary finite field,
so the base-change tower is already expressible.

\medskip
\noindent\textbf{Further avenues.}
(a) \emph{Higher vertical moments.} Theorem~\ref{thm:vertmom} refines the global second
moment by the arithmetic of $-3$; the fourth vertical moment should involve $\chi(-1)$ and a
further conic count, giving arithmetic-sensitive Chebyshev bounds on each vertical line.
(b) \emph{Other families.} The reduction applies verbatim to $y^2=x^n+ax+b$ and to
hyperelliptic families, where the innermost $b$-sum is again quadratic.
(c) \emph{Modular invariants for other moduli.} Corollaries~\ref{cor:mod3}
and~\ref{cor:mod4} give $3\mid\#E$ and $4\mid\#E$ from $q$ mod $3$ and $q$ mod $4$; a
systematic search for congruences forcing $m\mid\#E$ via torsion other than $2$-torsion
appears tractable by the same route.
(d) \emph{Distributional refinement.} Trace histograms are strikingly close to a semicircle;
the moment ladder is the standard route to a Sato--Tate-type limit law, and the exact second
moment is its first nontrivial rung.

