"""Character-sum point counting for y^2 = x^3 + a x + b over F_p."""

from __future__ import annotations

from typing import List, Tuple


def legendre_symbol(c: int, p: int) -> int:
    """Quadratic character chi(c) in {-1,0,1} for an odd prime p. Cost: O(log p)."""
    c %= p
    if c == 0:
        return 0
    return 1 if pow(c, (p - 1) // 2, p) == 1 else -1


def character_sum(a: int, b: int, p: int) -> int:
    """S(a,b) = sum_{x in F_p} chi(x^3 + a x + b).  Cost: O(p log p)."""
    total = 0
    for x in range(p):
        total += legendre_symbol((x * x % p * x + a * x + b) % p, p)
    return total


def point_count(a: int, b: int, p: int) -> int:
    """#E(F_p) = p + 1 + S(a,b), including the point at infinity."""
    return p + 1 + character_sum(a, b, p)


def frobenius_trace(a: int, b: int, p: int) -> int:
    """a(a,b) = p + 1 - #E(F_p) = -S(a,b)."""
    return -character_sum(a, b, p)


def discriminant(a: int, b: int, p: int) -> int:
    """4a^3 + 27b^2 mod p; the curve is nonsingular iff this is nonzero."""
    return (4 * pow(a, 3, p) + 27 * pow(b, 2, p)) % p


def full_family(p: int) -> List[Tuple[int, int, int, int]]:
    """All (a, b, #E, trace) for the p^2 short Weierstrass curves over F_p.

    Tabulating chi once costs O(p log p); the sweep then costs O(p^3) additions.
    """
    chi: List[int] = [legendre_symbol(c, p) for c in range(p)]
    cube: List[int] = [x * x % p * x % p for x in range(p)]
    out: List[Tuple[int, int, int, int]] = []
    for a in range(p):
        base = [(cube[x] + a * x) % p for x in range(p)]
        for b in range(p):
            s = 0
            for x in range(p):
                s += chi[(base[x] + b) % p]
            out.append((a, b, p + 1 + s, -s))
    return out


if __name__ == "__main__":
    p = 13
    print(f"p = {p}: y^2 = x^3 + 1 has {point_count(0, 1, p)} points, "
          f"trace {frobenius_trace(0, 1, p)}")
    fam = full_family(p)
    print("second moment:", sum(t * t for _, _, _, t in fam), "vs p^3-p^2 =", p ** 3 - p ** 2)

"""Exact collision counts and vertical second moments over F_p."""

from __future__ import annotations

from typing import Dict, List


def legendre_symbol(c: int, p: int) -> int:
    """Quadratic character chi(c) in {-1,0,1} for an odd prime p."""
    c %= p
    if c == 0:
        return 0
    return 1 if pow(c, (p - 1) // 2, p) == 1 else -1


def collisions_bruteforce(a: int, p: int) -> int:
    """#{(x,y) : x^3 + a x = y^3 + a y} by bucketing values.  Cost: O(p)."""
    buckets: Dict[int, int] = {}
    for x in range(p):
        v = (x * x % p * x + a * x) % p
        buckets[v] = buckets.get(v, 0) + 1
    return sum(m * m for m in buckets.values())


def collisions_closed_form(a: int, p: int) -> int:
    """Closed form:  N(0) = 2p-1 + (p-1)chi(-3),  N(a) = 2p-1 - chi(-3) - chi(-a/3).

    Derived from the conic count #{x^2+xy+y^2 = -a}.  Cost: O(log p).
    """
    chi3 = legendre_symbol(-3, p)
    if a % p == 0:
        return 2 * p - 1 + (p - 1) * chi3
    inv3 = pow(3, p - 2, p)
    return 2 * p - 1 - chi3 - legendre_symbol((-a) * inv3 % p, p)


def vertical_second_moment(a: int, p: int) -> int:
    """sum_b a(a,b)^2 = p * N(a) - p^2, from the two-shift correlation identity."""
    return p * collisions_closed_form(a, p) - p * p


def vertical_second_moment_formula(a: int, p: int) -> int:
    """The fully explicit closed forms of the vertical second moment."""
    chi3 = legendre_symbol(-3, p)
    if a % p == 0:
        return p * (p - 1) * (1 + chi3)
    inv3 = pow(3, p - 2, p)
    chia = legendre_symbol((-a) * inv3 % p, p)
    return p * p - p * (1 + chi3 + chia)


def global_second_moment(p: int) -> int:
    """sum_{a,b} a(a,b)^2, assembled from the vertical moments; equals p^3 - p^2."""
    return sum(vertical_second_moment_formula(a, p) for a in range(p))


if __name__ == "__main__":
    for p in [5, 7, 11, 13, 17, 19, 23, 29, 31]:
        ok = all(collisions_bruteforce(a, p) == collisions_closed_form(a, p) for a in range(p))
        print(f"p={p:3d}  collision closed form exact: {ok}   "
              f"global second moment {global_second_moment(p)} vs {p**3 - p**2}")
